"""Execution traces attached by providers rather than generated by models."""

from __future__ import annotations

import hashlib

from pydantic import BaseModel, Field

class ExecutionProcess(BaseModel):
    """Preserve a provider's event sequence and reported token usage.

    Attributes:
        events: Original event or message objects in order, including tool calls,
            intermediate messages, and lifecycle events. Fields remain unchanged.
        usage: Provider-reported invocation usage mapping. Cached tokens are
            preserved as reported, not added to input tokens.
    """

    events: list[dict[str, object]] = Field(default_factory=list)
    usage: dict[str, object] = Field(default_factory=dict)


def digest(value: str) -> str:
    """Compute a stable execution or publication identity.

    Args:
        value: Canonical material identifying one operation.

    Returns:
        SHA-256 digest.
    """
    key = hashlib.sha256(value.encode()).hexdigest()
    return key
